  HTMLDivElement,
  Omit<IPreviewPanelProps, 'onDrag' | 'onDragStart' | 'onDragEnd' | 'onAnimationStart'>
>(
  (
    {
      maxHeight,
      minZoom = 0.25,
      maxZoom = 4,
      initialZoom = 1,
      showControls = true,
      unsafeHtml,
      children,
      className,
      style,
      onStateChange,
      syncState,
      dir,
      ...rest
