              </m.span>
            ) : icon ? (
              <m.span key="icon" {...spinIn} transition={contentTransition} className="inline-flex">
                {icon}
              </m.span>
            ) : null}
          </AnimatePresence>
          {!isCollapsed && children && children}
          {!isCollapsed && secondIcon && secondIcon}
        </m.button>
      </LazyMotion>
    )
  },
)
