                              }}
                              renderDay={renderDay}
                            />
                          )
                        })}
                      </div>
                    ))}
                  </div>
                </div>
              )
            })}
          </div>
          {renderFooter?.(state.months)}
        </div>
        <announcer.AnnouncerPortal />
      </div>
    )
  },
)
Calendar.displayName = 'Calendar'

