                <AnimatePresence mode="wait" initial={false} custom={navDirection}>
                  <m.div
                    key={monthKey}
                    custom={navDirection}
                    variants={{
                      enter: (dir: number) => ({
                        opacity: 0,
                        y: dir * 6,
                        filter: BLUR,
                      }),
                      center: { opacity: 1, y: 0, filter: 'blur(0px)' },
                      exit: (dir: number) => ({
                        opacity: 0,
                        y: dir * -6,
                        filter: BLUR,
