                                      <m.div
                                        key={day.date.getTime()}
                                        variants={{
                                          hidden: { opacity: 0, y: 4, filter: 'blur(2px)' },
                                          visible: { opacity: 1, y: 0, filter: 'blur(0px)' },
                                        }}
                                        className="flex-1">
                                        <MotionCalendarDayCell
                                          day={day}
                                          dayProps={dayProps}
                                          isFocused={isFocused}
                                          isSelectedSingle={isSelectedSingle}
                                          isFirstInRow={dayIdx === 0}
                                          isLastInRow={dayIdx === 6}
