                            </m.div>
                          </div>
                        </div>
                      )
                    })}
                  </m.div>
                </AnimatePresence>
              </div>
              {renderFooter?.(state.months)}
            </div>
            <announcer.AnnouncerPortal />
          </div>
        </m.div>
      </LazyMotion>
    )
  },
